Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1000111;
const long long MOD = 1000000007;

long long visited[MAXN], countArr[MAXN];

long long modPower(long long base, int exponent) {
    long long result = 1;
    while (exponent > 0) {
        if (exponent & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exponent >>= 1;
    }
    return result;
}

int main() {
    int p, k;
    cin >> p >> k;
    if (k == 0) {
        cout << modPower(p, p - 1) << endl;
        return 0;
    }
    if (k == 1) {
        cout << modPower(p, p) << endl;
        return 0;
    }
    memset(visited, 0, sizeof(visited));
    memset(countArr, 0, sizeof(countArr));
    int totalSteps = 0;
    for (int i = 1; i < p; i++) {
        if (visited[i]) continue;
        long long u = i, cnt = 0;
        while (!visited[u]) {
            visited[u] = 1;
            u = (u * k) % p;
            cnt++;
        }
        countArr[cnt]++;
    }
    long long answer = 1;
    for (int i = 1; i <= p - 1; i++) {
        if (countArr[i] == 0) continue;
        long long tmp = modPower((i * countArr[i] + 1) % MOD, countArr[i]);
        answer = (answer * tmp) % MOD;
    }
    cout << answer << endl;
    return 0;
}
</original_code>
